/*
 * ONE PRESS FROM THE LINK IN A "RICHARD REPLIED" EMAIL, WITH NO SESSION (DBU-07).
 * The signature (HMAC-SHA256 with the unsubscribeKey secret over 'dbu-unsubscribe:v1:' + account,
 * made by shared/Message mail) is recomputed and compared in constant time. A match turns message
 * emails off, keeping the first stamp. EVERY OUTCOME ANSWERS THE SAME (a bad signature, an unknown
 * account, a success), so this public door cannot tell anyone which accounts exist, and it can only
 * ever turn mail OFF. It runs on the page's button, never on opening the link: mail scanners follow links.
 */
(async () => {
  try {
    const u = String(Inputs.u || '');
    const s = String(Inputs.s || '').toLowerCase();
    const secret = globalThis._noodl_get_secret ? globalThis._noodl_get_secret('unsubscribeKey') : null;
    const key = secret && secret.found ? String(secret.value) : '';
    let same = false;
    if (key && u && u.length < 100) {
      const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
      const want = Array.from(new Uint8Array(await crypto.subtle.sign('HMAC', k, new TextEncoder().encode('dbu-unsubscribe:v1:' + u))))
        .map((b) => b.toString(16).padStart(2, '0')).join('');
      let diff = s.length === want.length ? 0 : 1;
      for (let i = 0; i < want.length; i++) diff |= (s.charCodeAt(i) || 0) ^ want.charCodeAt(i);
      same = diff === 0;
    }
    if (same) {
      const users = await Noodl.Records.query('_User', { objectId: { equalTo: u } }, { limit: 2, plain: true });
      if (users.length === 1 && !users[0].emailOptOutAt) {
        await Noodl.Records.save(u, { emailOptOutAt: new Date().toISOString() }, { className: '_User' });
      }
    } else {
      console.warn('[dbu:unsubscribe] a link that does not verify');
    }
  } catch (e) {
    console.error('[dbu:unsubscribe]', String((e && e.message) || e));
  }
  Outputs.done();
})();
